<section id="messages" class="screen">
    <div class="screen-head left">
        <p class="tiny-label">COMMUNICATION</p>
        <h2>MESSAGES & <span>CONNECTIONS</span></h2>
        <p>Keep conversations with clients and collaborators in one place.</p>
    </div><div class="message-filters"><button class="message-filter active" type="button">Other</button><button class="message-filter" type="button">Jobs</button><button class="message-filter" type="button">Unread</button><button class="message-filter" type="button">Connections</button><button class="message-filter" type="button">Starred</button></div><div class="messages-layout">
        <div class="conversation-list">
            <div class="conversation-list-head">
                <h3>Inbox</h3><input id="messageSearch" type="search" placeholder="Search messages" aria-label="Search messages"></div><div id="conversationList">
                    
                </div></div><div class="chat-window"><div class="chat-head"><h3 id="chatName">Select a conversation</h3><p id="chatSub">Messages will appear here.</p></div><div class="chat-messages" id="chatMessages"></div><form class="chat-form" id="chatForm"><input id="chatInput" placeholder="Write a message..." autocomplete="off"><button class="pill-btn pill-orange" type="submit">Send</button></form></div></div></section>
